/**
 * 弹窗管理
 */
cc.Class({
    extends: cc.Component,

    properties: {
        _freeGameTimesSucces:null,
        _startAddFreeWinCoin:false,
        _winCoin:0,
        _wheelInitPosY:0,
        _BonusStartButton:null,
        _winCoinCollect:null,
        _winCoinAutoClose:false,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._BonusStartButton = cc.find("bg/pressToStart/startButton",this.node)
        Global.btnClickEvent(this._BonusStartButton,this.clossBonusStart,this)
        this._winCoinCollect = cc.find("bg/winCoin/collectButton",this.node)
        Global.btnClickEvent(this._winCoinCollect,this.closeWinCoin,this)
    },

    start () {

    },

    showWin(){
        this.node.active = true
        let popBg = cc.find("bg",this.node)
        popBg.scale = 1.2
        cc.tween(popBg).to(0.2,{scale:1}).start()
        let effect = cc.find("T_01",this.node)
        effect.active = true
        let effectSp = effect.getComponent(sp.Skeleton)
        effectSp.setAnimation(0,"animation",false)
        effectSp.setCompleteListener(()=>{
            effect.active = false
            effectSp.setCompleteListener(null)
        })
    },

    hideWin(){
        let popBg = cc.find("bg",this.node)
        popBg.scale = 1
        cc.tween(popBg).to(0.1,{scale:1.2}).to(0.3,{scale:0.1}).call(()=>{
            this.node.active = false
            if(this._freeGameTimesSucces){
                this._freeGameTimesSucces()
                this._freeGameTimesSucces = null
            }
        }).start()
    },

    specialFormatNumToComma(num){
        var unitArr = ['', 'K', 'M', 'B', 'T', 'Q'];
        let sum = 0
        while (num > 9999999) {
            num /= 1000
            sum++
        }
        return Global.FormatNumToComma(num)+unitArr[sum]
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    //bonusStart///////////////////////////////
    initBonusStart(){
        this._BonusStartButton.getComponent(cc.Button).interactable = false
        let bg = cc.find("bg",this.node)
        for (let i = 0; i < bg.children.length; i++) {
            const element = bg.children[i];
            element.active = false
        }
        let BonusRoot = cc.find("bg/BonusRoot",this.node)
        BonusRoot.active = true
        BonusRoot.opacity = 255
    },

    showBonusStart(){
        return new Promise(async (sucess,failed)=>{
            this._freeGameTimesSucces = sucess
            this.showWin()
            this.initBonusStart()
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.frame2)
            await this.awaitTime(1.5)
            let BonusRoot = cc.find("bg/BonusRoot",this.node)
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.frame2)
            cc.tween(BonusRoot).to(0.4,{opacity:0}).start()
            let pressToStart = cc.find("bg/pressToStart",this.node)
            pressToStart.active = true
            pressToStart.opacity = 0
            this.unschedule(this.loopStartButton)
            cc.tween(pressToStart).to(0.4,{opacity:255}).call(()=>{
                this.schedule(this.loopStartButton,1)
                this._BonusStartButton.getComponent(cc.Button).interactable = true
            }).start()
        })
    },

    loopStartButton(){
        let pressToStart = cc.find("bg/pressToStart",this.node)
        cc.tween(pressToStart).to(0.3,{scale:1.1}).to(0.8,{scale:1}).start()
    },

    clossBonusStart(){
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.click1)
        this.unschedule(this.loopStartButton)
        this._BonusStartButton.getComponent(cc.Button).interactable = false
        this.hideWin()
    },
    ////////////////////////////////////////////////

    //freeWinFree///////////////////////////////
    initFreeWinFree(freeNum){
        let bg = cc.find("bg",this.node)
        for (let i = 0; i < bg.children.length; i++) {
            const element = bg.children[i];
            element.active = false
        }
        let freeWinFree = cc.find("bg/freeWinFree",this.node)
        freeWinFree.active = true
        cc.find("bg/freeWinFree/bg/label",this.node).getComponent(cc.Label).string = freeNum
    },

    showFreeWinFree(freeNum){
        return new Promise(async (sucess,failed)=>{
            this._freeGameTimesSucces = sucess
            this.showWin()
            this.initFreeWinFree(freeNum)
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.frame2)
            await this.awaitTime(2)
            this.hideWin()
        })
    },

    ////////////////////////////////////////////////

    ////////winCoin///////////////////////////////////////
    initWinCoin(coin){
        this._winCoin = coin
        this._winCoinCollect.getComponent(cc.Button).interactable = true
        let bg = cc.find("bg",this.node)
        for (let i = 0; i < bg.children.length; i++) {
            const element = bg.children[i];
            element.active = false
        }
        let winCoin = cc.find("bg/winCoin",this.node)
        winCoin.active = true
    },

    showWinCoin(coin,autoclose){
        return new Promise(async (sucess,failed)=>{
            this._winCoinAutoClose = autoclose
            this._freeGameTimesSucces = sucess
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.frame2)
            this.showWin()
            this.initWinCoin(coin)

            let winCoinLabel = cc.find("bg/winCoin/bg/label",this.node)
            this._startAddFreeWinCoin = true
            Global.doRoallNumEff(winCoinLabel,Math.floor(coin*0.1),coin,2.5,()=>{
                this._startAddFreeWinCoin = false
                if(autoclose){
                    this.hideWin()
                }
            },null,0,true);
        })
    },

    closeWinCoin(){
        if(this._winCoinAutoClose){
            return
        }
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.click1)
        if(this._startAddFreeWinCoin){
            this._startAddFreeWinCoin = false
            let winCoin = cc.find("bg/winCoin/bg/label",this.node)
            winCoin.stopAllActions()
            let winCoinLabel = winCoin.getComponent(cc.Label)
            winCoinLabel.string = Global.FormatNumToComma(this._winCoin)
            return
        }
        this._winCoinCollect.getComponent(cc.Button).interactable = false
        this.hideWin()
    },
    ///////////////////////////////////////////////////////////
    // update (dt) {},
});
