cc.Class({
    extends: require("LMSlots_Reel_Base"),

    properties: {
        
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    ShowScatterEffect(){
        let node = cc.find("mask/scatterAni",this.node)
        if(node){
            node.active = true
            let nodeSp = node.getComponent(sp.Skeleton)
            nodeSp.setAnimation(0,"animation",false)
            nodeSp.setCompleteListener(()=>{
                node.active = false
            })
        }
        else{
            cc.log("未找到加速节点：mask/scatterAni");
        }
    },

    //重写
    playReelStop(){
        this._super()
    },

    // update (dt) {},
});
