
let jackpotNames = ['Mini','Minor','Major','Grand','MAXI','Bigger']  //节点名称
/**
 * 埃及的幻想
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
       _qiePin:null,   //切屏节点
       _node_freeGame:null,  //免费游戏节点
       _isInFree:false,
       _tipsIndex:1,
       _wheelResult:null,   //转盘结果
       _isBackUp:false,
    },

    onLoad(){
        this._super()
        this._qiePin = cc.find("qiepingNode",this.node.parent)
        this._node_freeGame = cc.find("node_free_game",this.node.parent)
        this.schedule(this.showTips,10)
        cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA,this.onRecvClickButton,this);
    },

    RegisterEvent:function(){

    },

    onDestroy(){
        cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA,this.onRecvClickButton,false,this);
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    //重写
    ShowWinTrace:function(){
        this._super()
    },

    //重写
    StartMove:function(){
        // if(!Global.SlotsSoundMgr.playingBgm){
        //     Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.base_bgm)
        // }

        Global.SlotsSoundMgr.playNormalBgm()

        this._bStopRightnow = null
        this._gameInfo = null

        //top状态更新
        this._topScript.StartMove()

        //清理数据
        cc.vv.gameData.ClearOneRoundData()

        //每列转起来
        this.MoveReels(this._reels)

        

        //设置停止时间
        //就是收到结果后，如果多少秒会开始停止
        this._stopTime = this.GetStopTime()
        let parNode = cc.find("top_ani",this.node)
        if(parNode){
            parNode.removeAllChildren()
        }
        if((cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()) || this._bottomScript._bAutoModel){
            this.SetTimeScale(1.2)
        }else{
            this.SetTimeScale(1)
        }

        let total = cc.vv.gameData.GetTotalFree()
        let rest = cc.vv.gameData.GetFreeTime()
    
        if(total > 0){
            let freeGameTip = cc.find("Canvas/safe_node/freeGameInfo")
            if(freeGameTip){
                let usdTimes = cc.find("freeGameTimes",freeGameTip)
                let last = cc.find("theme113_fg_last",freeGameTip)
                if(rest > 0){
                    last.active = false
                    usdTimes.active = true
                    usdTimes.getComponent(cc.Label).string = rest
                }else{
                    last.active = true
                    usdTimes.active = false
                }
            }
        }

        let PrizePoolRoot = cc.find('Canvas/safe_node/LMSlots_PrizePool_1')
        if(PrizePoolRoot){
            for (let i = 0; i < jackpotNames.length; i++) { //可能连续中多个jackpot，最后隐藏的时候将所有特效都隐藏
                const prizeName = jackpotNames[i];
                let targetJpNode = cc.find('prizePool_'+prizeName,PrizePoolRoot)
                if(targetJpNode){
                    let winRoot = targetJpNode.getChildByName('winRoot')
                    let lbl_num = targetJpNode.getChildByName('lbl_num')
                    winRoot.active = false
                    lbl_num.active = true
                }
            }
        }
    },

    showJackpotWinEffect(index){
        let safeNode = cc.find('Canvas/safe_node')
        let jpNode = safeNode.getComponentInChildren('LMSlotMachine_PrizePool')
        if(jpNode){
            const element = jackpotNames[index];
            let targetJpNode = cc.find('prizePool_'+element,jpNode.node.parent)
            if(targetJpNode){
                let winRoot = targetJpNode.getChildByName('winRoot')
                let lbl_num = targetJpNode.getChildByName('lbl_num')
                if(winRoot){
                    winRoot.active = true
                    lbl_num.active = false
                }
            }
        }
    },

    /**
     * 显示切屏动画
     */
    showQiePin:function(midCallBack,finalCallBack){
        if(this._qiePin && !this._qiePin.active){
            this._qiePin.active = true
            let mask = cc.find("mask",this._qiePin)
            mask.height = 0
            mask.opacity = 255
            let lizi1 = cc.find("bg/CutTheScreen_lizi01_1",mask)
            lizi1.active = true
            let lizi2 = cc.find("bg/CutTheScreen_lizi02_1",mask)
            lizi2.active = true
            let lizi3 = cc.find("CutTheScreen_lizi03_1",this._qiePin)
            lizi3.active = true
            lizi3.y = cc.winSize.height/2
            let qieping_di = cc.find("bg/qieping_di02",mask)
            qieping_di.y = cc.winSize.height/2
            let qiepinTime = 1.2
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.transition)
            cc.tween(mask).to(qiepinTime,{height:cc.winSize.height}).call(()=>{
                lizi1.active = false
                lizi2.active = false
                lizi3.active = false
                if(midCallBack){
                    midCallBack()
                }
            }).to(0.5,{opacity:0}).call(()=>{
                this._qiePin.active = false
                if(finalCallBack){
                    finalCallBack()
                }
            }).start()
            cc.tween(qieping_di).to(qiepinTime,{y:-cc.winSize.height/2}).start()
            cc.tween(lizi3).to(qiepinTime,{y:-cc.winSize.height/2}).call(()=>{
                lizi3.y = cc.winSize.height/2
            }).start()
        }
    },

    /**
     * 显示免费游戏
     */
    showFreeGame(){
        let freePickGame = {"pick":[{"state":false,"idx":1},{"state":false,"idx":2},{"state":false,"idx":3},{"state":false,"idx":4},{"state":false,"idx":5},{"state":false,"idx":6},{"state":false,"idx":7},{"state":false,"idx":8},{"state":false,"idx":9},{"state":false,"idx":10},{"state":false,"idx":11},{"state":false,"idx":12},{"state":false,"idx":13},{"state":false,"idx":14},{"state":false,"idx":15},{"state":false,"idx":16},{"state":false,"idx":17},{"state":false,"idx":18},{"state":false,"idx":19},{"state":false,"idx":20}],"info":[{"max":3,"type":1,"num":0,"desc":"F5M2"},{"max":3,"type":2,"num":0,"desc":"F7M2"},{"max":3,"type":3,"num":0,"desc":"F10M2"},{"max":3,"type":4,"num":0,"desc":"F11M2"},{"max":3,"type":5,"num":0,"desc":"F15M20"},{"max":3,"type":6,"num":0,"desc":"F20M3"}],"result":[]}
        return new Promise((success,failed)=>{
            this.showQiePin(()=>{
                this.recaveryFreeGame(freePickGame,success)
            },()=>{
                Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.frame_bgm)
            })
        })
    },

    recaveryFreeGame(data,success){
        this._node_freeGame.active = true
        let pickNode = this._node_freeGame.getComponent("Jormengander_pick")
        pickNode.initData(success,data)
    },

    /**
     * 隐藏免费游戏
     * @param {function} midCallBack 中途回调
     */
    hideFreeGame(midCallBack){
        return new Promise((sucess,falied)=>{
            this.showQiePin(()=>{
                this._node_freeGame.active = false
                if(midCallBack){
                    midCallBack()
                }
                Global.SlotsSoundMgr.stopBgm()
                Global.SlotsSoundMgr.playingBgm = false
            },()=>{
                sucess()
            })
        })
    },

    ShowWinCoin(nAddWin,nTotalWin,bUpdateBalance){
        return new Promise(async (sucess, failed)=>{
            this.ShowBottomWin(nAddWin,nTotalWin,bUpdateBalance,sucess)
        });
    },

    //全部列都停止了,重写
    //处理停下后的中奖情况，这里多数情况需要根据自己的逻辑来处理
    async OnSpinEnd(){
        this._bottomScript.ShowBtnsByState("moveing_1")
        let total = cc.vv.gameData.GetTotalFree()
        let rest = cc.vv.gameData.GetFreeTime()

        if(this._gameInfo.rapidPayData){  //先显示repid结果
            let rapidPayWinCoin = this._gameInfo.rapidPayData.win
            if(rapidPayWinCoin > 0){
                for (let i = 0; i < this._gameInfo.rapidPayData.idxs.length; i++) {
                    const key = this._gameInfo.rapidPayData.idxs[i];
                    let symbol = this.GetSymbolByIdx(Number(key))
                    if(symbol){
                        symbol.playWinAnimation()
                    }
                }
            }
            if(!(total > 0 && total != rest)){   //非免费游戏才弹窗
                if(this._gameInfo.rapidPayData.idxs.length >= 5){  //需要弹窗提示，赢得jackpot，播放特效
                    let index = this._gameInfo.rapidPayData.idxs.length - 5
                    if(index >= 3){
                        index++
                    }
                    if(index === 6){
                        index = 3
                    }
                    let PrizePoolRoot = cc.find('Canvas/safe_node/LMSlots_PrizePool_1')
                    if(PrizePoolRoot){
                        const element = jackpotNames[index];
                        let targetJpNode = cc.find('prizePool_'+element,PrizePoolRoot)
                        let PrizePool = targetJpNode.getComponent("LMSlotMachine_PrizePool")
                        if(!PrizePool.isLocked()){//奖池未被锁定
                            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bell_fg)
                            await this.awaitTime(1)
                            this.showJackpotWinEffect(index)
                            await cc.vv.gameData.getPopWinManage().showWinJackpot(rapidPayWinCoin,this._gameInfo.rapidPayData.idxs.length)
                        }
                    } 
                }
            }
        }

        if(this._gameInfo.rapidPlatinumData){  //先显示repid结果
            let rapidPayWinCoin = this._gameInfo.rapidPlatinumData.win
            if(rapidPayWinCoin > 0){
                for (let i = 0; i < this._gameInfo.rapidPlatinumData.idxs.length; i++) {
                    const key = this._gameInfo.rapidPlatinumData.idxs[i];
                    let symbol = this.GetSymbolByIdx(Number(key))
                    if(symbol){
                        symbol.playWinAnimation()
                    }
                }
            }
            // if(this._gameInfo.rapidPayData.idx.length >= 5){  //需要弹窗提示，赢得jackpot，播放特效
            //     Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bell)
            //     await this.awaitTime(1)
            //     let index = this._gameInfo.rapidPayData.idx.length - 5
            //     if(index >= 3){
            //         index++
            //     }
            //     this.showJackpotWinEffect(index)
            //     await cc.vv.gameData.getPopWinManage().showWinJackpot(rapidPayWinCoin,this._gameInfo.rapidPayData.idx.length)
            // }
        }

        if(total > 0 && total != rest){
            let freeGameTip = cc.find("Canvas/safe_node/freeGameInfo")
            if(freeGameTip){
                let winCoin = cc.find("winCoin",freeGameTip)
                let nTotal = cc.vv.gameData.GetGameTotalFreeWin()
                if(nTotal>0){
                    winCoin.getComponent(cc.Label).string = cc.vv.gameData.getPopWinManage().specialFormatNumToComma(nTotal,99999)
                }else{
                    winCoin.getComponent(cc.Label).string = ""
                }
            }
        }

        //显示中奖路线
        this.ShowWinTrace()
        //显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin()
        let nTotal = nWin
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
            nTotal = cc.vv.gameData.GetGameTotalFreeWin()
        }else{
            if(this._gameInfo.freeGameBonus && !this._gameInfo.freeGameBonus.isEnd){
                nWin = this._gameInfo.freeGameBonus.winCoin
                nTotal = nWin
            }
        }

        await this.ShowWinCoin(nWin,nTotal,true)

        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){  //免费次数中
            if(this._gameInfo.freeResult){
                if(this._gameInfo.freeResult.freeInfo && this._gameInfo.freeResult.freeInfo.scatterIdx){//免费中免费
                    for (let i = 0; i < this._gameInfo.freeResult.freeInfo.scatterIdx.length; i++) {
                        const key = this._gameInfo.freeResult.freeInfo.scatterIdx[i];
                        let symbol = this.GetSymbolByIdx(Number(key))
                        if(symbol){
                            symbol.playWinAnimation()
                        }
                    }
                    if(this._gameInfo.freeResult.freeInfo.freeCnt > 0){
                        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bell_fg)
                        await this.awaitTime(2)
                        await this.CheckFreeEnterFreeGame(this._gameInfo.freeResult.freeInfo.freeCnt);
                    }
                }
            }
        }else{
            if(this._gameInfo.wheelInfo){  //触发转盘
                cc.find("Canvas/safe_node/LMSlots_PrizePool_1/tips").active = false
                cc.find("Canvas/safe_node/LMSlots_PrizePool_1/tip_bonusSpine").active = true
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.bell_fg)
                await this.awaitTime(2)
                await cc.vv.gameData.getBottomPopWinManage().showBonusStart()
                await this.awaitTime(0.5)
                await cc.vv.gameData.getPopWinManage().showWheelGame(this._gameInfo.wheelInfo.cfg)
                if(this._wheelResult.info.type === "coin"){
                    await this.awaitTime(1)
                    Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.rollNum)
                    await cc.vv.gameData.getBottomPopWinManage().showWinCoin(this._wheelResult.info.num,true)
                    let nWin = this._wheelResult.info.num
                    let nTotal = nWin
                    cc.vv.gameData.AddCoin(nWin)
                    await this.ShowWinCoin(nWin,nTotal,true)
                }else if(this._wheelResult.info.type === "free"){
                    await this.showFreeGame()
                    if(this._gameInfo.freeResult){
                        if(this._gameInfo.freeResult.freeInfo && this._gameInfo.freeResult.freeInfo.scatterIdx){//免费中免费
                            for (let i = 0; i < this._gameInfo.freeResult.freeInfo.scatterIdx.length; i++) {
                                const key = this._gameInfo.freeResult.freeInfo.scatterIdx[i];
                                let symbol = this.GetSymbolByIdx(Number(key))
                                if(symbol){
                                    symbol.playWinAnimation()
                                }
                            }
                        }
                    }
                    await this.CheckEnterFreeGame()
                }
                cc.find("Canvas/safe_node/LMSlots_PrizePool_1/tips").active = true
                cc.find("Canvas/safe_node/LMSlots_PrizePool_1/tip_bonusSpine").active = false
            }
        }

        //触发退出免费
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() == 0){
            await this.CheckExitFreeGame();
        }  
        this.CanDoNextRound()
    },

    //断线重连的显示,重写
    //可根据自己断线逻辑重写
    async ReconnectShow(){
        let rest = cc.vv.gameData.GetFreeTime()
        if(rest){
            this.ShowGameview(true)
            Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.free_bgm)
            this.CanDoNextRound()
        }else{
            this.ShowGameview(false)
        }

        let select = cc.vv.gameData.getSelect()
        if(select){
            if(select.state){  //触发了小游戏
                this._bottomScript.ShowBtnsByState("moveing_1")
                if(select.rtype === 1){  //触发了转盘
                    await cc.vv.gameData.getPopWinManage().showWheelGame(cc.vv.gameData._deskInfo.wheelInfo.cfg)
                    if(this._wheelResult.info.type === "coin"){
                        await this.awaitTime(1)
                        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.rollNum)
                        await cc.vv.gameData.getBottomPopWinManage().showWinCoin(this._wheelResult.info.num,true)
                        let nWin = this._wheelResult.info.num
                        let nTotal = nWin
                        cc.vv.gameData.AddCoin(nWin)
                        await this.ShowWinCoin(nWin,nTotal,true)
                    }else if(this._wheelResult.info.type === "free"){
                        await this.showFreeGame()
                        await this.CheckEnterFreeGame()
                    }
                }else if(select.rtype === 2){
                    await new Promise((sucess,failed)=>{
                        this.recaveryFreeGame(cc.vv.gameData._deskInfo.freePickGame,sucess)
                    })
                    await this.CheckEnterFreeGame()
                }else if(select.rtype === 3){
                    await new Promise((sucess,failed)=>{
                        let pickNode = this._node_freeGame.getComponent("Jormengander_pick")
                        pickNode.recavery(sucess)
                    })
                    await this.CheckEnterFreeGame()
                }
            }
        }

        this.CanDoNextRound()
    },

    //检查退出免费
    async CheckExitFreeGame(){
        return new Promise(async (sucess, failed)=>{
            let nWin = cc.vv.gameData.GetGameTotalFreeWin()
            let nTotal = nWin
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.frame1)
            await cc.vv.gameData.getBottomPopWinManage().showWinCoin(nWin)
            await new Promise((suc,fail)=>{
                this.showQiePin(()=>{
                    this.ShowGameview(false)
                    this.Resume()
                },()=>{
                    suc();
                    Global.SlotsSoundMgr.stopBgm()
                    Global.SlotsSoundMgr.playingBgm = false
                })
            })
            await this.ShowWinCoin(nWin,nTotal,true)
            cc.vv.gameData.SetTotalFree(0)
            sucess()
        });
    },

    //免费进入免费
    async CheckFreeEnterFreeGame(num){
        return new Promise(async (sucess,failed)=>{
            await cc.vv.gameData.getBottomPopWinManage().showFreeWinFree(num)
            await this.awaitTime(1)
            sucess()
        })
    },

    //检查进入免费
    async CheckEnterFreeGame(){
        return new Promise(async (sucess, failed)=>{
            await this.hideFreeGame(()=>{
                this.ShowGameview(true)
            })
            this.Backup()
            for (let i = 0; i < this._reels.length; i++) {
                const reel = this._reels[i];
                for (let j = 0; j < reel._symbols.length; j++) {
                    const symbol = reel._symbols[j];
                    symbol.ShowNormal()
                }
            }
            Global.SlotsSoundMgr.playBgm(Global.SlotsSoundMgr.free_bgm)
            await this.awaitTime(1)
            sucess();
        });
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview:function(bFree){
        this._isInFree = bFree
        if(bFree){
            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()
        
            //显示免费次数
            this._bottomScript.ShowFreeModel(true,total-rest,total)
            let nTotal = cc.vv.gameData.GetTotalFreeWin() + this._bottomScript.getCurrentWin()
            this._bottomScript.SetWin(nTotal)
            let freeGameTip = cc.find("Canvas/safe_node/freeGameInfo")
            if(freeGameTip){
                let usdTimes = cc.find("freeGameTimes",freeGameTip)
                let last = cc.find("theme113_fg_last",freeGameTip)
                let winCoin = cc.find("winCoin",freeGameTip)
                if(nTotal>0){
                    winCoin.getComponent(cc.Label).string = cc.vv.gameData.getPopWinManage().specialFormatNumToComma(nTotal,99999)
                }else{
                    winCoin.getComponent(cc.Label).string = ""
                }
                if(rest > 0){
                    last.active = false
                    usdTimes.active = true
                    usdTimes.getComponent(cc.Label).string = rest
                }else{
                    last.active = true
                    usdTimes.active = false
                }
                let mult = cc.vv.gameData.GetFreeGameMult()
                if(mult === 2){
                    cc.find("theme113_fg_allpays/theme113_fg_num3",freeGameTip).active = false
                    cc.find("theme113_fg_allpays/theme113_fg_num2",freeGameTip).active = true
                }else{
                    cc.find("theme113_fg_allpays/theme113_fg_num3",freeGameTip).active = true
                    cc.find("theme113_fg_allpays/theme113_fg_num2",freeGameTip).active = false
                }
            }
        }
        else{
            this._bottomScript.ShowFreeModel(false)
        }

        //可能还需要显示免费背景图
        // let normalBg = cc.find("Canvas/safe_node/icon")
        // let normalFree = cc.find("Canvas/safe_node/icon_free")
        // if(normalFree){ //存在免费游戏背景才执行下面的逻辑
        //     if(normalBg){
        //         normalBg.active = !bFree
        //     }
        //     normalFree.active = bFree
        // }
        let freeGameTip = cc.find("Canvas/safe_node/freeGameInfo")
        if(freeGameTip){
            freeGameTip.active = bFree
        }
        let jackpotPool = cc.find("Canvas/safe_node/LMSlots_PrizePool_1")
        if(jackpotPool){
            jackpotPool.active = !bFree
        }
    },


    //重写
    //备份当前状态
    Backup() {
        this._super()
        this._isBackUp = true
    },

    //重写
    //恢复到保存的状态
    Resume() {
        if(this._isBackUp){
            this._topAniNode.removeAllChildren()
            this._isBackUp = false
        }
        this._super()
    },

    showTips(){
        if(this._tipsIndex > 1){
            this._tipsIndex = 0
        }
        let tips = []
        tips[tips.length] = cc.find("Canvas/safe_node/LMSlots_PrizePool_1/tips/tip_1")
        tips[tips.length] = cc.find("Canvas/safe_node/LMSlots_PrizePool_1/tips/tip_2")
        for (let i = 0; i < tips.length; i++) {
            const element = tips[i];
            element.active = false
        }
        let effect = cc.find("Canvas/safe_node/LMSlots_PrizePool_1/tips/base_QH")
        effect.active = true
        let effectSp = effect.getComponent(sp.Skeleton)
        effectSp.setAnimation(0,"animation",false)
        effectSp.setCompleteListener(()=>{
            effect.active = false
            effectSp.setCompleteListener(null)
        })
        tips[this._tipsIndex].active = true
        tips[this._tipsIndex].scale = 0.1
        cc.tween(tips[this._tipsIndex]).to(0.2,{scale:1.3}).to(0.2,{scale:1}).start()
        this._tipsIndex++
    },

    async onRecvClickButton(msg){
        if(msg.code == 200){
            if(msg.data.rtype == 1){  
                this._wheelResult = msg.data
                await cc.vv.gameData.getPopWinManage().setWheelResult(msg.data)
            }else if(msg.data.rtype == 2){
                if(msg.data.idx){
                    let pickNode = this._node_freeGame.getComponent("Jormengander_pick")
                    pickNode.click(msg.data)
                }
            }else if(msg.data.rtype == 3){
                let pickNode = this._node_freeGame.getComponent("Jormengander_pick")
                pickNode.startFreeGame(msg.data)
            }
        }
    },

    //可以进入下一局
    //如果是自动模式/免费模式，调用此接口会开始自动旋转，
    //普通模式的话，调用此接口。按钮都会变成可点击状态
    CanDoNextRound:function(){
        this._topScript.StopMove()
        this._bottomScript.CanDoNextRound()
    },
});
