cc.Class({
    extends: cc.Component,

    properties: {
        _buttonList:[],  //按钮列表
        _pickEffectList:[],  //点击spine动画列表
        _success:null,  //Promise完成函数
        _jinduList:[],   //进度条列表
        _clickButton:false,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        for (let i = 1; i < 21; i++) {
            let button = cc.find("waysRoot/pickBg/button"+i,this.node)
            this._buttonList[this._buttonList.length] = button
            Global.btnClickEvent(button,this.onButtonClick.bind(this,i),this)
        }
        for (let i = 1; i < 21; i++) {
            let pickeffect = cc.find("waysRoot/pickBg/pick_effect"+i,this.node)
            this._pickEffectList[this._pickEffectList.length] = pickeffect
        }
        for (let i = 1; i < 7; i++) {
            let jindu = cc.find("jinduRoot/jindu"+i,this.node)
            this._jinduList[this._jinduList.length] = jindu
        }
    },

    start () {

    },

    transformType(type){
        let ret = [5,4,3,2,1,0,9]
        return ret[type-1]
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    changeNodeColor(node,color){
        node.color = color
        for (let i = 0; i < node.children.length; i++) {
            const element = node.children[i];
            element.color = color
        }
    },

    // update (dt) {},

    /**
     * 初始化中奖类型
     * @param {function} success Promise 完成函数
     * @param {*} data 数据
     */
    initData(success,data){
        this._success = success
        for (let i = 0; i < data.pick.length; i++) {
            const element = data.pick[i];
            if(element.state){
                this._buttonList[i].getComponent(cc.Button).interactable = false
                this.setButtonResult(this._buttonList[i],element.type)
            }else{
                this._buttonList[i].getComponent(cc.Button).interactable = true
                cc.find("result",this._buttonList[i]).active = false
            }
            this.changeNodeColor(cc.find("result",this._buttonList[i]),cc.color(255,255,255))
            let win = cc.find("win",this._buttonList[i])
            win.active = false
        }
        for (let i = 0; i < data.info.length; i++) {
            const element = data.info[i];
            this.setJinDu(this._jinduList[element.type - 1],element.num)
        }
        for (let i = 0; i < this._pickEffectList.length; i++) {
            const element = this._pickEffectList[i];
            element.active = false
        }
        this._clickButton = false
    },

    recavery(success){
        this._success = success
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.uid = Global.playerData.uid;
        req.gameid = cc.vv.gameData._gameId;
        req.data = {};
        req.data.rtype = 3;
        cc.vv.NetManager.send(req);
    },

    setButtonResult(button,type){
        let result = cc.find("result",button)
        result.active = true
        for (let i = 0; i < result.children.length; i++) {
            const element = result.children[i];
            element.active = false
        }
        let trueType = this.transformType(type)
        cc.find("theme113_pick_"+trueType,result).active = true
    },

    setJinDu(node,val){
        let jindu = cc.find("jindu",node)
        let jindu1 = cc.find("jindu1",jindu)
        let jindu2 = cc.find("jindu2",jindu)
        let barMask = cc.find("barMask",node)
        let jindutiao = cc.find("jindu2/jindutiao_02",node)
        switch (val) {
            case 1:
                barMask.width = jindu1.x
                jindutiao.x = jindu1.x
                break;
            case 2:
                barMask.width = jindu2.x
                jindutiao.x = jindu2.x
                break;
            case 3:
                barMask.width = jindu.width
                jindutiao.x = jindu.width
                break;
            default:
                barMask.width = 0
                jindutiao.x = 0
                break
        }
    },

    changeJinDu(node,val){
        let jindu = cc.find("jindu",node)
        let jindu1 = cc.find("jindu1",jindu)
        let jindu2 = cc.find("jindu2",jindu)
        let barMask = cc.find("barMask",node)
        let jindutiao = cc.find("jindu2/jindutiao_02",node)
        switch (val) {
            case 1:
                cc.tween(barMask).to(0.2,{width:jindu1.x}).start()
                cc.tween(jindutiao).to(0.2,{x:jindu1.x}).start()
                break;
            case 2:
                cc.tween(barMask).to(0.2,{width:jindu2.x}).start()
                cc.tween(jindutiao).to(0.2,{x:jindu2.x}).start()
                break;
            case 3:
                cc.tween(barMask).to(0.2,{width:jindu.width}).start()
                cc.tween(jindutiao).to(0.2,{x:jindu.width}).call(()=>{
                    let fullEffect = cc.find("fullEffect",node)
                    fullEffect.active = true
                    let fullEffectSp = fullEffect.getComponent(sp.Skeleton)
                    fullEffectSp.setAnimation(0,"animation",false)
                    fullEffectSp.setCompleteListener(()=>{
                        fullEffect.active = false
                        fullEffectSp.setCompleteListener(null)
                    })
                }).start()
                break;
            default:
                barMask.width = 0
                jindutiao.x = 0
                break
        }
    },

    removeByVal(val){
        for (let i = 0; i < this._typeList.length; i++) {
            const element = this._typeList[i];
            if(element === val){
                this._typeList.splice(i,1)
                break
            }
        }
    },

    /**
     * 按钮点击
     * @param {number} index 按钮索引
     */
    onButtonClick(index){
        if(this._clickButton){
            return
        }
        this._clickButton = true
        let req = {c: MsgId.SLOT_SUBGAME_DATA};
        req.uid = Global.playerData.uid;
        req.gameid = cc.vv.gameData._gameId;
        req.data = {};
        req.data.rtype = 2;
        req.data.idx = index;
        cc.vv.NetManager.send(req);
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.click2)
    },

    async click(data){
        this._clickButton = false
        let index = data.idx - 1
        let type = this.transformType(data.type) 
        this._buttonList[index].getComponent(cc.Button).interactable = false
        this._pickEffectList[index].active = true
        let effectSp = this._pickEffectList[index].getComponent(sp.Skeleton)
        effectSp.setAnimation(0,"animation_"+type,false)
        effectSp.setCompleteListener(async ()=>{
            // this._pickEffectList[index].active = false
            // this.setButtonResult(this._buttonList[index],data.type)
            effectSp.setCompleteListener(null)
            for (let i = 0; i < data.topInfo.length; i++) {
                const element = data.topInfo[i];
                this.changeJinDu(this._jinduList[element.type - 1],element.num)
            }
            if(data.select.rtype === 3){  //游戏结束
                for (let i = 0; i < this._buttonList.length; i++) {
                    const element = this._buttonList[i];
                    element.getComponent(cc.Button).interactable = false
                }
                this.showWinNode(data.type,data.pick)
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.threesame)
                await this.awaitTime(3.5)
                await cc.vv.gameData.getPopWinManage().showFreeGameTimes(data.result.num,data.result.mult)
                let req = {c: MsgId.SLOT_SUBGAME_DATA};
                req.uid = Global.playerData.uid;
                req.gameid = cc.vv.gameData._gameId;
                req.data = {};
                req.data.rtype = 3;
                cc.vv.NetManager.send(req);
            }
        })
    },

    startFreeGame(data){
        cc.vv.gameData.SetFreeTime(data.allFreeCnt)
        cc.vv.gameData.SetTotalFree(data.freeCnt)
        cc.vv.gameData.SetFreeGameMult(data.addMult)
        if(this._success){
            this._success()
        }
    },

    showWinNode(type,pick){
        for (let i = 0; i < pick.length; i++) {
            const element = pick[i];
            if(element.state){
                if(element.type === type || element.type === 7){
                    let win = cc.find("win",this._buttonList[i])
                    win.active = true
                }
            }else{
                this.setButtonResult(this._buttonList[i],element.type)
                this.changeNodeColor(cc.find("result",this._buttonList[i]),cc.color(60,60,60))
            }
        }
    },
});
