/**
 * 弹窗管理
 */
let winName = {
    win_jackpot:0,
    freeGameTimes:1,
    wheelGame:2,
}
cc.Class({
    extends: cc.Component,

    properties: {
        _showWinList:[],
        _freeGameTimesSucces:null,
        _startAddFreeWinCoin:false,
        _jackpotCoin:0,
        _freeGameCoin:0,
        _wheelInitPosY:0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._showWinList[winName.win_jackpot] = cc.find("show_win_jackpot",this.node)
        this._showWinList[winName.freeGameTimes] = cc.find("show_freeGameTimes",this.node)
        this._showWinList[winName.wheelGame] = cc.find("wheelGame",this.node)
        let startButton = cc.find("startButton",this._showWinList[winName.freeGameTimes])
        Global.btnClickEvent(startButton,this.clossFreeGameTimes,this)
        Global.btnClickEvent(cc.find("collectButton",this._showWinList[winName.win_jackpot]),this.clossWinJackpot,this)
    },

    start () {

    },

    showWin(){
        this.node.active = true
        let popBg = cc.find("popup",this.node)
        popBg.opacity = 0
        cc.tween(popBg).to(0.3,{opacity:255}).start()
    },

    hideWin(callBack){
        let popBg = cc.find("popup",this.node)
        cc.tween(popBg).to(0.3,{opacity:0}).call(()=>{
            if(callBack){
                callBack()
            }
            this.node.active = false
            for (let i = 0; i < this._showWinList.length; i++) {
                const element = this._showWinList[i];
                element.active = false
            }
        }).start()
    },

    specialFormatNumToComma(num,change){
        var unitArr = ['', 'K', 'M', 'B', 'T', 'Q'];
        let sum = 0
        while (num > change) {
            num /= 1000
            sum++
        }
        return Global.FormatNumToComma(num)+unitArr[sum]
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

    //winjackpot///////////////////////////////
    initWinJackpot(coinNum,jackpotNum){
        let collectButton = cc.find("collectButton",this._showWinList[winName.win_jackpot])
        collectButton.getComponent(cc.Button).interactable = true
        this._jackpotCoin = coinNum
        let winCoin = cc.find("freeSpinsRoot/label",this._showWinList[winName.win_jackpot])
        winCoin.getComponent(cc.Label).string = Global.FormatNumToComma(Math.floor(coinNum*0.1))
        let rapidNum = cc.find("rapidNum",this._showWinList[winName.win_jackpot])
        for (let i = 0; i < rapidNum.children.length; i++) {
            const element = rapidNum.children[i];
            element.active = false
        }
        cc.find("them113_jackpot_RapidPay_"+jackpotNum,rapidNum).active = true
    },

    showWinJackpot(coinNum,jackpotNum){
        return new Promise((sucess,failed)=>{
            this._freeGameTimesSucces = sucess
            this.showWin()
            this.initWinJackpot(coinNum,jackpotNum)
            for (let i = 0; i < this._showWinList.length; i++) {
                const element = this._showWinList[i];
                element.active = false
            }
            this._showWinList[winName.win_jackpot].active = true
            let animation = this._showWinList[winName.win_jackpot].getComponent(cc.Animation)
            animation.play("popWin")
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.frame3)
            animation.on("stop",()=>{
                this._startAddFreeWinCoin = true
                let winCoin = cc.find("freeSpinsRoot/label",this._showWinList[winName.win_jackpot])
                Global.doRoallNumEff(winCoin,Math.floor(coinNum*0.1),coinNum,2.5,()=>{
                    this._startAddFreeWinCoin = false
                },null,0,true);
            })
            this.scheduleOnce(this.clossWinJackpot,10)
        })
    },

    clossWinJackpot(){
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.click1)
        if(this._startAddFreeWinCoin){
            this._startAddFreeWinCoin = false
            let winCoin = cc.find("freeSpinsRoot/label",this._showWinList[winName.win_jackpot])
            winCoin.stopAllActions()
            let winCoinLabel = winCoin.getComponent(cc.Label)
            winCoinLabel.string = Global.FormatNumToComma(this._jackpotCoin)
            return
        }
        this.unschedule(this.clossWinJackpot)
        cc.tween(this._showWinList[winName.win_jackpot]).to(0.3,{scale:0.1}).start()
        this.hideWin(()=>{
            if(this._freeGameTimesSucces){
                this._freeGameTimesSucces()
                this._freeGameTimesSucces = null
            }
        })
        let collectButton = cc.find("collectButton",this._showWinList[winName.win_jackpot])
        collectButton.getComponent(cc.Button).interactable = false
    },
    ////////////////////////////////////////////////

    //freeGameTimes///////////////////////////////
    initFreeGameTimes(freeNum,mult){
        let startButton = cc.find("startButton",this._showWinList[winName.freeGameTimes])
        startButton.getComponent(cc.Button).interactable = true
        startButton.active = false
        let freeNumLabel = cc.find("freeSpinsRoot/label",this._showWinList[winName.freeGameTimes])
        freeNumLabel.getComponent(cc.Label).string = freeNum
        if(mult === 2){
            cc.find("theme113_tankuang2_with/theme113_tankuang2_X2",this._showWinList[winName.freeGameTimes]).active = true
            cc.find("theme113_tankuang2_with/theme113_tankuang2_X3",this._showWinList[winName.freeGameTimes]).active = false
        }else{
            cc.find("theme113_tankuang2_with/theme113_tankuang2_X2",this._showWinList[winName.freeGameTimes]).active = false
            cc.find("theme113_tankuang2_with/theme113_tankuang2_X3",this._showWinList[winName.freeGameTimes]).active = true
        }
    },

    showFreeGameTimes(freeNum,mult){
        return new Promise((sucess,failed)=>{
            this._freeGameTimesSucces = sucess
            this.showWin()
            this.initFreeGameTimes(freeNum,mult)
            for (let i = 0; i < this._showWinList.length; i++) {
                const element = this._showWinList[i];
                element.active = false
            }
            this._showWinList[winName.freeGameTimes].active = true
            let animation = this._showWinList[winName.freeGameTimes].getComponent(cc.Animation)
            animation.play("popWin")
            animation.on("stop",()=>{
                let startButton = cc.find("startButton",this._showWinList[winName.freeGameTimes])
                startButton.active = true
            })
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.frame1)
        })
    },

    clossFreeGameTimes(){
        Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.click1)
        cc.tween(this._showWinList[winName.freeGameTimes]).to(0.3,{scale:0.1}).start()
        this.hideWin(()=>{
            if(this._freeGameTimesSucces){
                this._freeGameTimesSucces()
                this._freeGameTimesSucces = null
            }
        })
        let startButton = cc.find("startButton",this._showWinList[winName.freeGameTimes])
        startButton.getComponent(cc.Button).interactable = false
    },
    ////////////////////////////////////////////////

    ////////showWheelGame///////////////////////////////////////
    initWheelGame(data){
        let winNode = this._showWinList[winName.wheelGame]
        this._wheelInitPosY = winNode.y
        for (let i = 0; i < data.length; i++) {
            const element = data[i];
            if(element === "FREE"){
                let node = cc.find("rollNode/node"+(i+1),winNode)
                cc.find("free",node).active = true
                cc.find("jackpot",node).active = false
            }else if(element === "JACPOT"){
                let node = cc.find("rollNode/node"+(i+1),winNode)
                cc.find("free",node).active = false
                cc.find("jackpot",node).active = true
            }else{
                let node = cc.find("rollNode/node"+(i+1),winNode)
                let label = cc.find("label",node)
                label.getComponent(cc.Label).string = this.specialFormatNumToComma(element,9999999)
            }
        }
    },

    showWheelGame(data){
        return new Promise(async (sucess,failed)=>{
            this._freeGameTimesSucces = sucess
            this.showWin()
            this.initWheelGame(data)
            for (let i = 0; i < this._showWinList.length; i++) {
                const element = this._showWinList[i];
                element.active = false
            }
            let winNode = this._showWinList[winName.wheelGame]
            winNode.active = true
            cc.find("choiceEffect",winNode).active = false
            let rollNode = cc.find("rollNode",winNode)
            rollNode.angle = 0
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wheel_move1)
            cc.tween(winNode).to(0.3,{y:548 - cc.winSize.height/2},{easing:"backOut"}).start()
            await this.awaitTime(1)
            // this.setWheelResult({idx:3})
            let req = {c: MsgId.SLOT_SUBGAME_DATA};
            req.uid = Global.playerData.uid;
            req.gameid = cc.vv.gameData._gameId;
            req.data = {};
            req.data.rtype = 1;
            cc.vv.NetManager.send(req);
        })
    },

    setWheelResult(result){
        return new Promise(async (sucess,failed)=>{
            let winNode = this._showWinList[winName.wheelGame]
            let rollNode = cc.find("rollNode",winNode)
            let rusltAngle = (result.idx - 1) * 15
            rusltAngle -= 360*10
            Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wheel_spin)
            cc.tween(rollNode).to(7,{angle:rusltAngle},{easing:"quadInOut"}).call(async ()=>{
                cc.find("choiceEffect",winNode).active = true
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wheel_stop)
                await this.awaitTime(2)
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.wheel_move2)
                cc.tween(winNode).to(0.3,{y:this._wheelInitPosY},{easing:"backIn"}).start()
                this.hideWin(()=>{
                    if(this._freeGameTimesSucces){
                        this._freeGameTimesSucces()
                        this._freeGameTimesSucces = null
                    }
                    sucess()
                })
            }).start()
        })
    },
    ///////////////////////////////////////////////////////////
    // update (dt) {},
});
